+ */
+
+#ifndef MATMUL_BLOCK_BLOCK_MN_EQUAL_ONE_H
+#define MATMUL_BLOCK_BLOCK_MN_EQUAL_ONE_H
+#include "./block_mmad.h"
+#include "../utils/layout_utils.h"
